diff --git a/.asc/workflow-automatic.json b/.asc/workflow-automatic.json
index 6a0b118..65c87dc 100644
--- a/.asc/workflow-automatic.json
+++ b/.asc/workflow-automatic.json
@@ -1,115 +1,38 @@
 {
   "env": {
     "APP_ID": "6760480210",
-    "ALPHA_GROUP_ID": "00c630e2-6c85-4636-824c-90c4156aa7f5",
-    "EXTERNAL_GROUP_ID": "cc8a412f-d86c-439e-ae8e-1db4c8ab4791",
     "VERSION": "",
     "BUILD_NUMBER": "",
-    "WHAT_TO_TEST": "",
     "CONFIRM": ""
   },
-  "before_all": "echo 'Starting release workflow for U Do' && asc auth status",
+  "before_all": "echo 'Starting App Store submission workflow for U Do' && asc auth status",
   "workflows": {
-    "release-alpha-auto": {
-      "description": "Build, upload, and distribute to internal TestFlight alpha group using automatic signing. Optional: VERSION=x.x.x BUILD_NUMBER=xxx",
-      "steps": [
-        {
-          "name": "get_next_build",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nif [ -n \"$BUILD_NUMBER\" ]; then echo \"Using provided build number: $BUILD_NUMBER\" && echo \"$BUILD_NUMBER\" > /tmp/new_build_number.txt; else NEXT_BUILD=$(asc builds latest --app 6760480210 --platform IOS --next | jq -r '.nextBuildNumber') && echo \"Next build number: $NEXT_BUILD\" && echo \"$NEXT_BUILD\" > /tmp/new_build_number.txt; fi\nSTAGECMD\nscripts/run-stage.sh \"Resolving build number\" \"$UDO_CMD\""
-        },
-        {
-          "name": "update_build_number",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nNEW_BUILD=$(cat /tmp/new_build_number.txt) && echo \"Setting build number to $NEW_BUILD\" && cd apps/frontend/ios && sed -i '' \"s/CURRENT_PROJECT_VERSION = [0-9]*/CURRENT_PROJECT_VERSION = $NEW_BUILD/g\" UDo.xcodeproj/project.pbxproj && sed -i '' 's/TARGETED_DEVICE_FAMILY = \"1,2\"/TARGETED_DEVICE_FAMILY = 1/g' UDo.xcodeproj/project.pbxproj && /usr/libexec/PlistBuddy -c \"Set :CFBundleVersion $NEW_BUILD\" UDo/Info.plist\nSTAGECMD\nscripts/run-stage.sh \"Setting build number\" \"$UDO_CMD\""
-        },
-        {
-          "name": "sync_marketing_version",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nnode scripts/sync-ios-version.mjs\nSTAGECMD\nscripts/run-stage.sh \"Syncing marketing version\" \"$UDO_CMD\""
-        },
-        {
-          "name": "resolve_node",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nNODE_BINARY=$(command -v node || true) && if [ -z \"$NODE_BINARY\" ]; then echo \"NODE_BINARY not found in PATH\" >&2; exit 1; fi && echo \"$NODE_BINARY\" > /tmp/node_binary.txt\nSTAGECMD\nscripts/run-stage.sh \"Resolving Node\" \"$UDO_CMD\""
-        },
-        {
-          "name": "sync_pods",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nNODE_BINARY=$(cat /tmp/node_binary.txt) && export NODE_BINARY && pnpm install --frozen-lockfile && cd apps/frontend/ios && pod install\nSTAGECMD\nscripts/run-stage.sh --silent \"Syncing CocoaPods\" \"$UDO_CMD\""
-        },
-        {
-          "name": "clean",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nNODE_BINARY=$(cat /tmp/node_binary.txt) && export NODE_BINARY && cd apps/frontend/ios && xcodebuild clean -workspace UDo.xcworkspace -scheme \"UDo\" -configuration Release\nSTAGECMD\nscripts/run-stage.sh --silent \"Cleaning\" \"$UDO_CMD\""
-        },
-        {
-          "name": "archive",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nNODE_BINARY=$(cat /tmp/node_binary.txt) && export NODE_BINARY && cd apps/frontend/ios && { set -a; [ -f ../.env.production ] && . ../.env.production; set +a; } && export SENTRY_ALLOW_FAILURE=true && xcodebuild archive -workspace UDo.xcworkspace -scheme \"UDo\" -configuration Release -archivePath /tmp/UDo.xcarchive -destination \"generic/platform=iOS\" DEVELOPMENT_TEAM=2M44US8WCT -allowProvisioningUpdates -authenticationKeyPath \"$ASC_API_KEY_PATH\" -authenticationKeyID \"$ASC_API_KEY_ID\" -authenticationKeyIssuerID \"$ASC_API_ISSUER_ID\"\nSTAGECMD\nscripts/run-stage.sh --silent \"Building (archive)\" \"$UDO_CMD\""
-        },
-        {
-          "name": "export_ipa",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\ncd apps/frontend/ios && xcodebuild -exportArchive -archivePath /tmp/UDo.xcarchive -exportPath /tmp/UDo-export -exportOptionsPlist ../ExportOptions-Automatic.plist -allowProvisioningUpdates -authenticationKeyPath \"$ASC_API_KEY_PATH\" -authenticationKeyID \"$ASC_API_KEY_ID\" -authenticationKeyIssuerID \"$ASC_API_ISSUER_ID\"\nSTAGECMD\nscripts/run-stage.sh --silent \"Exporting IPA\" \"$UDO_CMD\""
-        },
-        {
-          "name": "find_ipa",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nexport IPA_PATH=$(find /tmp/UDo-export -name '*.ipa' | head -1) && echo \"IPA_PATH=$IPA_PATH\"\nSTAGECMD\nscripts/run-stage.sh \"Locating IPA\" \"$UDO_CMD\""
-        },
-        {
-          "name": "upload",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nexport IPA_PATH=$(find /tmp/UDo-export -name '*.ipa' | head -1) && asc builds upload --app 6760480210 --ipa \"$IPA_PATH\" --wait\nSTAGECMD\nscripts/run-stage.sh --silent \"Uploading to TestFlight\" \"$UDO_CMD\""
-        },
-        {
-          "name": "distribute",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nasc builds latest --app 6760480210 --platform IOS | jq -r '.data.id' | xargs -I {} asc builds add-groups --build {} --group \"$ALPHA_GROUP_ID\"\nSTAGECMD\nscripts/run-stage.sh \"Distributing to alpha group\" \"$UDO_CMD\""
-        },
-        {
-          "name": "summary",
-          "run": "BUILD=$(cat /tmp/new_build_number.txt 2>/dev/null); scripts/release-summary.sh \"Alpha · build $BUILD uploaded & distributed to internal group\""
-        }
-      ]
-    },
-    "release-beta-promote": {
-      "description": "Promote an existing alpha build to external TestFlight beta review. Optional: BUILD_NUMBER=xxx WHAT_TO_TEST=\"...\" CONFIRM=1",
+    "release-store-promote": {
+      "description": "Submit one App Store-eligible TestFlight build. Required: VERSION=x.y.z BUILD_NUMBER=n. Optional: CONFIRM=1.",
       "steps": [
         {
-          "name": "resolve_build",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(if [ -n \"$BUILD_NUMBER\" ]; then asc builds find --app \"$APP_ID\" --build-number \"$BUILD_NUMBER\" | jq -r '.data.id'; else asc builds latest --app \"$APP_ID\" --platform IOS | jq -r '.data.id'; fi); if [ -z \"$BUILD_ID\" ] || [ \"$BUILD_ID\" = \"null\" ]; then echo \"Could not resolve a build (BUILD_NUMBER='$BUILD_NUMBER'). Check it exists and has finished processing.\" >&2; exit 1; fi; echo \"Resolved build: $BUILD_ID\" && echo \"$BUILD_ID\" > /tmp/beta_build_id.txt\nSTAGECMD\nscripts/run-stage.sh \"Resolving build\" \"$UDO_CMD\""
-        },
-        {
-          "name": "upsert_test_notes",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(cat /tmp/beta_build_id.txt); if [ -n \"$WHAT_TO_TEST\" ]; then EXISTING=$(asc builds test-notes list --build \"$BUILD_ID\" | jq -r '.data[] | select(.attributes.locale == \"en-US\") | .id // empty'); if [ -n \"$EXISTING\" ]; then echo \"Updating existing test notes ($EXISTING)\" && asc builds test-notes update --id \"$EXISTING\" --whats-new \"$WHAT_TO_TEST\"; else echo 'Creating new test notes (en-US)' && asc builds test-notes create --build \"$BUILD_ID\" --locale en-US --whats-new \"$WHAT_TO_TEST\"; fi; else echo 'WHAT_TO_TEST not set; leaving existing notes (if any) untouched'; fi\nSTAGECMD\nscripts/run-stage.sh \"Updating test notes\" \"$UDO_CMD\""
-        },
-        {
-          "name": "validate",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(cat /tmp/beta_build_id.txt) && asc validate testflight --app \"$APP_ID\" --build \"$BUILD_ID\"\nSTAGECMD\nscripts/run-stage.sh \"Validating for TestFlight\" \"$UDO_CMD\""
+          "name": "require_inputs",
+          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nif [ -z \"$VERSION\" ] || [ -z \"$BUILD_NUMBER\" ]; then echo 'VERSION and BUILD_NUMBER are required. This workflow never selects the latest build.' >&2; exit 1; fi; echo \"$VERSION\" > /tmp/store_version.txt; echo \"$BUILD_NUMBER\" > /tmp/store_build_number.txt\nSTAGECMD\nscripts/run-stage.sh \"Checking submission inputs\" \"$UDO_CMD\""
         },
         {
-          "name": "add_to_external_group",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(cat /tmp/beta_build_id.txt) && asc builds add-groups --build \"$BUILD_ID\" --group \"$EXTERNAL_GROUP_ID\"\nSTAGECMD\nscripts/run-stage.sh \"Adding to external group\" \"$UDO_CMD\""
-        },
-        {
-          "name": "submit_for_review",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(cat /tmp/beta_build_id.txt) && if [ \"$CONFIRM\" = \"1\" ]; then asc testflight review submit --build \"$BUILD_ID\" --confirm; else echo 'Dry-run: would submit '\"$BUILD_ID\"' for external beta review. Re-run with CONFIRM=1 to actually submit.'; fi\nSTAGECMD\nscripts/run-stage.sh \"Submitting for beta review\" \"$UDO_CMD\""
-        }
-      ]
-    },
-    "release-store-promote": {
-      "description": "Promote an existing TestFlight build to App Store production review. Required: VERSION=x.x.x. Optional: BUILD_NUMBER=xxx CONFIRM=1",
-      "steps": [
-        {
-          "name": "require_version",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nif [ -z \"$VERSION\" ]; then VERSION=$(node -p \"require('./package.json').version.split('-')[0]\") && echo \"VERSION not provided; defaulting to repo version: $VERSION\"; fi && echo \"$VERSION\" > /tmp/store_version.txt && echo \"Target App Store version: $VERSION. It must already exist in App Store Connect (create via the UI or 'asc versions create' first).\"\nSTAGECMD\nscripts/run-stage.sh \"Resolving version\" \"$UDO_CMD\""
+          "name": "resolve_exact_build",
+          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nVERSION=$(cat /tmp/store_version.txt); BUILD_NUMBER=$(cat /tmp/store_build_number.txt); BUILD_JSON=$(asc builds list --app \"$APP_ID\" --version \"$VERSION\" --build-number \"$BUILD_NUMBER\" --processing-state all); BUILD_COUNT=$(printf '%s' \"$BUILD_JSON\" | jq -er '.data | if type == \"array\" then length else error(\"build list response is not an array\") end'); if [ \"$BUILD_COUNT\" -ne 1 ]; then echo \"Expected one iOS build for version $VERSION and build $BUILD_NUMBER; found $BUILD_COUNT.\" >&2; exit 1; fi; BUILD_ID=$(printf '%s' \"$BUILD_JSON\" | jq -er '.data[0].id'); echo \"$BUILD_ID\" > /tmp/store_build_id.txt; echo \"Resolved build: $BUILD_ID\"\nSTAGECMD\nscripts/run-stage.sh \"Resolving exact build\" \"$UDO_CMD\""
         },
         {
-          "name": "resolve_build",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(if [ -n \"$BUILD_NUMBER\" ]; then asc builds find --app \"$APP_ID\" --build-number \"$BUILD_NUMBER\" | jq -r '.data.id'; else asc builds latest --app \"$APP_ID\" --platform IOS | jq -r '.data.id'; fi); if [ -z \"$BUILD_ID\" ] || [ \"$BUILD_ID\" = \"null\" ]; then echo \"Could not resolve a build (BUILD_NUMBER='$BUILD_NUMBER'). Check it exists and has finished processing.\" >&2; exit 1; fi; echo \"Resolved build: $BUILD_ID\" && echo \"$BUILD_ID\" > /tmp/store_build_id.txt\nSTAGECMD\nscripts/run-stage.sh \"Resolving build\" \"$UDO_CMD\""
+          "name": "require_app_store_eligible_build",
+          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(cat /tmp/store_build_id.txt); AUDIENCE=$(asc builds info --build \"$BUILD_ID\" | jq -er '.data.attributes.buildAudienceType'); if [ \"$AUDIENCE\" != \"APP_STORE_ELIGIBLE\" ]; then echo \"Build $BUILD_ID is $AUDIENCE, not APP_STORE_ELIGIBLE. Internal-only alpha builds cannot go to the App Store.\" >&2; exit 1; fi; echo \"Build audience: $AUDIENCE\"\nSTAGECMD\nscripts/run-stage.sh \"Checking build audience\" \"$UDO_CMD\""
         },
         {
           "name": "verify_version_exists",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nVERSION=$(cat /tmp/store_version.txt); VERSION_ID=$(asc versions list --app \"$APP_ID\" --platform IOS | jq -r --arg V \"$VERSION\" '.data[] | select(.attributes.versionString == $V) | .id // empty'); if [ -z \"$VERSION_ID\" ]; then echo \"App Store version $VERSION not found. Create it via App Store Connect UI or 'asc versions create --app $APP_ID --version $VERSION' before promoting.\" >&2; exit 1; fi; echo \"Version $VERSION exists (id: $VERSION_ID)\" && echo \"$VERSION_ID\" > /tmp/store_version_id.txt\nSTAGECMD\nscripts/run-stage.sh \"Verifying version exists\" \"$UDO_CMD\""
+          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nVERSION=$(cat /tmp/store_version.txt); VERSION_ID=$(asc versions list --app \"$APP_ID\" --platform IOS | jq -er --arg V \"$VERSION\" '.data[] | select(.attributes.versionString == $V) | .id' | head -n 1); if [ -z \"$VERSION_ID\" ]; then echo \"App Store version $VERSION was not found. Create it before submitting.\" >&2; exit 1; fi; echo \"$VERSION_ID\" > /tmp/store_version_id.txt\nSTAGECMD\nscripts/run-stage.sh \"Checking App Store version\" \"$UDO_CMD\""
         },
         {
           "name": "validate",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nVERSION_ID=$(cat /tmp/store_version_id.txt) && asc validate --app \"$APP_ID\" --version-id \"$VERSION_ID\" --platform IOS\nSTAGECMD\nscripts/run-stage.sh \"Validating\" \"$UDO_CMD\""
+          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nVERSION_ID=$(cat /tmp/store_version_id.txt); asc validate --app \"$APP_ID\" --version-id \"$VERSION_ID\" --platform IOS\nSTAGECMD\nscripts/run-stage.sh \"Validating submission\" \"$UDO_CMD\""
         },
         {
           "name": "submit_for_review",
-          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(cat /tmp/store_build_id.txt) && VERSION_ID=$(cat /tmp/store_version_id.txt) && VERSION=$(cat /tmp/store_version.txt) && if [ \"$CONFIRM\" = \"1\" ]; then asc submit create --app \"$APP_ID\" --version-id \"$VERSION_ID\" --build \"$BUILD_ID\" --confirm; else echo 'Dry-run: would submit build '\"$BUILD_ID\"' to App Store review for version '\"$VERSION\"' (id: '\"$VERSION_ID\"'). Re-run with CONFIRM=1 to actually submit.'; fi\nSTAGECMD\nscripts/run-stage.sh \"Submitting to App Store review\" \"$UDO_CMD\""
+          "run": "read -r -d '' UDO_CMD <<'STAGECMD' || true\nBUILD_ID=$(cat /tmp/store_build_id.txt); VERSION_ID=$(cat /tmp/store_version_id.txt); VERSION=$(cat /tmp/store_version.txt); if [ \"$CONFIRM\" = \"1\" ]; then asc submit create --app \"$APP_ID\" --version-id \"$VERSION_ID\" --build \"$BUILD_ID\" --confirm; else echo \"Dry-run: would submit build $BUILD_ID for App Store version $VERSION. Re-run with CONFIRM=1 to submit.\"; fi\nSTAGECMD\nscripts/run-stage.sh \"Submitting to App Store review\" \"$UDO_CMD\""
         }
       ]
     }

