new file mode 100755
index 0000000..e203b3f
--- /dev/null
+++ b/apps/frontend/scripts/check-ios-config-drift.mjs
@@ -0,0 +1,69 @@
+#!/usr/bin/env node
+/* eslint-disable import/no-nodejs-modules -- This release check reads checked-in native files. */
+/** Check the native settings that Expo config owns for the iOS archive. */
+import { readFileSync } from "node:fs";
+import { dirname, join } from "node:path";
+import { fileURLToPath } from "node:url";
+
+const frontendRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
+const appConfig = JSON.parse(
+  readFileSync(join(frontendRoot, "app.json"), "utf8")
+).expo;
+const infoPlist = readFileSync(
+  join(frontendRoot, "ios/UDo/Info.plist"),
+  "utf8"
+);
+const project = readFileSync(
+  join(frontendRoot, "ios/UDo.xcodeproj/project.pbxproj"),
+  "utf8"
+);
+const entitlements = readFileSync(
+  join(frontendRoot, "ios/UDo/UDo.entitlements"),
+  "utf8"
+);
+
+const failures = [];
+const expectMatch = (value, source, label) => {
+  if (!source.includes(value)) {
+    failures.push(`${label} does not match apps/frontend/app.json`);
+  }
+};
+
+expectMatch(
+  `<string>${appConfig.version}</string>`,
+  infoPlist,
+  "CFBundleShortVersionString"
+);
+expectMatch(
+  `MARKETING_VERSION = ${appConfig.version};`,
+  project,
+  "MARKETING_VERSION"
+);
+expectMatch(
+  `PRODUCT_BUNDLE_IDENTIFIER = ${appConfig.ios.bundleIdentifier};`,
+  project,
+  "PRODUCT_BUNDLE_IDENTIFIER"
+);
+
+if (
+  appConfig.ios.supportsTablet === false &&
+  !project.includes("TARGETED_DEVICE_FAMILY = 1;")
+) {
+  failures.push("TARGETED_DEVICE_FAMILY does not match supportsTablet: false");
+}
+
+if (
+  appConfig.plugins.includes("expo-apple-authentication") &&
+  !entitlements.includes("com.apple.developer.applesignin")
+) {
+  failures.push(
+    "Apple Sign In entitlement is missing for expo-apple-authentication"
+  );
+}
+
+if (failures.length > 0) {
+  console.error(`iOS config drift detected:\n- ${failures.join("\n- ")}`);
+  process.exit(1);
+}
+
+console.log("iOS config matches app.json for archive-critical settings.");

