diff --git a/packages/backend/convex/experimental/customFunctions.ts b/packages/backend/convex/experimental/customFunctions.ts
new file mode 100644
index 0000000..90457a1
--- /dev/null
+++ b/packages/backend/convex/experimental/customFunctions.ts
@@ -0,0 +1,39 @@
+/* eslint-disable import/no-relative-parent-imports -- These wrappers compose the shared actor boundary. */
+import { actorMutation, actorQuery } from "../customFunctions";
+
+import { assertExperimentalTester } from "./guard";
+
+type ExperimentalDefinition =
+  | ((ctx: unknown, args?: unknown) => unknown)
+  | {
+      handler: (ctx: unknown, args?: unknown) => unknown;
+      [key: string]: unknown;
+    };
+
+const guardedDefinition = (definition: ExperimentalDefinition) => {
+  const handler =
+    typeof definition === "function" ? definition : definition.handler;
+  const guardedHandler = async (ctx: unknown, args: unknown) => {
+    await assertExperimentalTester(
+      ctx as Parameters<typeof assertExperimentalTester>[0]
+    );
+    return handler(ctx, args);
+  };
+
+  return typeof definition === "function"
+    ? guardedHandler
+    : { ...definition, handler: guardedHandler };
+};
+
+/**
+ * Adds the tester allowlist after the shared actor wrapper resolves the signed-
+ * in app user. The cast preserves the generic actorQuery API for callers.
+ */
+export const experimentalQuery = ((definition: ExperimentalDefinition) =>
+  actorQuery(guardedDefinition(definition) as never)) as typeof actorQuery;
+
+/** See experimentalQuery. */
+export const experimentalMutation = ((definition: ExperimentalDefinition) =>
+  actorMutation(
+    guardedDefinition(definition) as never
+  )) as typeof actorMutation;

