@@ -0,0 +1,174 @@
+/* eslint-disable import/no-relative-parent-imports -- The test stays beside the experimental guard. */
+import { register } from "@convex-dev/better-auth/test";
+import { convexTest } from "convex-test";
+import { makeFunctionReference } from "convex/server";
+
+import schema from "../schema";
+import { createConvexTest, modules } from "../test.setup";
+import { createAuthedUser, createUser } from "../test_helpers";
+
+import {
+  assertExperimentalTester,
+  experimentalTesterEmails,
+  isExperimentalTester,
+} from "./guard";
+
+const experimentalTestModules = {
+  ...modules,
+  "./experimental/wrapperTestFunctions.test.ts": () =>
+    import("./wrapperTestFunctions.test"),
+};
+
+interface ExperimentalTestGlobals {
+  __experimentalWrapperTestSupport?: boolean;
+}
+
+const createExperimentalConvexTest = () => {
+  (
+    globalThis as typeof globalThis & ExperimentalTestGlobals
+  ).__experimentalWrapperTestSupport = true;
+  const t = convexTest(schema, experimentalTestModules);
+  register(t, "betterAuth");
+  return t;
+};
+
+const readActorSubject = makeFunctionReference<
+  "query",
+  Record<never, never>,
+  string
+>("experimental/wrapperTestFunctions.test:readActorSubject");
+const writeActorSubject = makeFunctionReference<
+  "mutation",
+  Record<never, never>,
+  string
+>("experimental/wrapperTestFunctions.test:writeActorSubject");
+
+const withTesterAllowlist = async (
+  allowlist: string | undefined,
+  test: () => Promise<void> | void
+) => {
+  const previous = process.env.EXPERIMENTAL_TESTER_EMAILS;
+  try {
+    if (allowlist === undefined) {
+      delete process.env.EXPERIMENTAL_TESTER_EMAILS;
+    } else {
+      process.env.EXPERIMENTAL_TESTER_EMAILS = allowlist;
+    }
+    await test();
+  } finally {
+    if (previous === undefined) {
+      delete process.env.EXPERIMENTAL_TESTER_EMAILS;
+    } else {
+      process.env.EXPERIMENTAL_TESTER_EMAILS = previous;
+    }
+  }
+};
+
+describe("experimental tester guard", () => {
+  it("normalizes comma-separated tester emails", () => {
+    expect(
