+    ).toStrictEqual(new Set(["one@example.com", "two@example.com"]));
+    expect(
+      isExperimentalTester(" TWO@EXAMPLE.COM ", "two@example.com")
+    ).toBeTruthy();
+  });
+
+  it("denies requests when the server allowlist is unset", async () => {
+    await withTesterAllowlist(undefined, async () => {
+      const t = createConvexTest();
+      const userId = await createUser(t, {
+        email: "alpha@example.com",
+        username: "alpha",
+      });
+
+      await expect(
+        t.run((ctx) =>
+          assertExperimentalTester({ actor: { subject: userId }, db: ctx.db })
+        )
+      ).rejects.toMatchObject({
+        data: {
+          code: "experimental_access_denied",
+          message: "Experimental features are not enabled for this account.",
+        },
+        name: "ConvexError",
+      });
+    });
+  });
+
+  it("allows only the user identified by the shared app actor", async () => {
+    await withTesterAllowlist(" ALPHA@EXAMPLE.COM ", async () => {
+      const t = createConvexTest();
+      const allowedUserId = await createUser(t, {
+        email: "alpha@example.com",
+        username: "alpha",
+      });
+      const blockedUserId = await createUser(t, {
+        email: "blocked@example.com",
+        username: "blocked",
+      });
+
+      await expect(
+        t.run((ctx) =>
+          assertExperimentalTester({
+            actor: { subject: allowedUserId },
+            db: ctx.db,
+          })
+        )
+      ).resolves.toBeNull();
+      await expect(
+        t.run((ctx) =>
+          assertExperimentalTester({
+            actor: { subject: blockedUserId },
+            db: ctx.db,
+          })
