+    const tryBothHandlers = (allowlist?: string) =>
+      withTesterAllowlist(allowlist, async () => {
+        const t = createExperimentalConvexTest();
+        const { authed } = await createAuthedUser(t, {
+          email: "blocked-wrapper@example.com",
+          username: "blocked-wrapper",
