new file mode 100644
index 0000000..5c3fa66
--- /dev/null
+++ b/packages/backend/convex/experimental/guard.ts
@@ -0,0 +1,51 @@
+/* eslint-disable import/no-relative-parent-imports -- This guard reads the shared app actor at the Convex boundary. */
+import { ConvexError } from "convex/values";
+
+import type { AppActor } from "../../server/actor";
+import type { Id } from "../_generated/dataModel";
+import type { QueryCtx } from "../_generated/server";
+
+const accessDenied = () =>
+  new ConvexError({
+    code: "experimental_access_denied",
+    message: "Experimental features are not enabled for this account.",
+  });
+
+export const normalizeExperimentalTesterEmail = (email: string): string =>
+  email.trim().toLowerCase();
+
+export const experimentalTesterEmails = (
+  rawAllowlist = process.env.EXPERIMENTAL_TESTER_EMAILS
+): ReadonlySet<string> =>
+  new Set(
+    rawAllowlist
+      ?.split(",")
+      .map(normalizeExperimentalTesterEmail)
+      .filter(Boolean)
+  );
+
+export const isExperimentalTester = (
+  email: string,
+  rawAllowlist = process.env.EXPERIMENTAL_TESTER_EMAILS
+): boolean =>
+  experimentalTesterEmails(rawAllowlist).has(
+    normalizeExperimentalTesterEmail(email)
+  );
+
+interface ExperimentalActorContext {
+  actor: Pick<AppActor<Id<"users">>, "subject">;
+  db: Pick<QueryCtx["db"], "get">;
+}
+
+/**
+ * Allows only signed-in app users whose email appears in the server-side
+ * allowlist. An unset or empty allowlist denies every request.
+ */
+export const assertExperimentalTester = async (
+  ctx: ExperimentalActorContext
+): Promise<void> => {
+  const user = await ctx.db.get("users", ctx.actor.subject);
+  if (!user || !isExperimentalTester(user.email)) {
+    throw accessDenied();
+  }
+};

