diff --git a/scripts/release-handoff.mjs b/scripts/release-handoff.mjs
new file mode 100644
index 0000000..65f4f9a
--- /dev/null
+++ b/scripts/release-handoff.mjs
@@ -0,0 +1,266 @@
+#!/usr/bin/env node
+
+import { execFileSync } from "node:child_process";
+
+const SHA_PATTERN = /^[0-9a-f]{40}$/i;
+const SKIP_ALPHA_PATTERN = /\[skip alpha\]/i;
+const ALLOWED_BRANCHES = new Set(["origin/next", "origin/main"]);
+const EXPERIMENTAL_BACKEND_PREFIX = "packages/backend/convex/experimental/";
+const GENERATED_BINDING_PATHS = new Set([
+  "packages/backend/convex/_generated/api.d.ts",
+  "packages/backend/convex/_generated/api.js",
+  "packages/backend/convex/_generated/dataModel.d.ts",
+  "packages/backend/convex/_generated/server.d.ts",
+  "packages/backend/convex/_generated/server.js",
+]);
+const RELEASE_COMMIT_PATTERN = /^chore\(release\): .+ \[skip ci\]$/u;
+const RELEASE_COMMIT_PATHS = new Set([
+  "apps/frontend/package.json",
+  "package.json",
+]);
+const REQUIRED_OPTIONS = ["sha", "branch", "event", "base"];
+
+export function hasSkipAlphaMarker(message) {
+  return SKIP_ALPHA_PATTERN.test(message);
+}
+
+export function isSafeBackendPath(path) {
+  return (
+    path.startsWith(EXPERIMENTAL_BACKEND_PREFIX) ||
+    GENERATED_BINDING_PATHS.has(path)
+  );
+}
+
+export function classifyBackendPaths(paths) {
+  const experimentalPaths = [];
+  const generatedBindingPaths = [];
+  const unsafePaths = [];
+
+  for (const path of paths.filter(Boolean)) {
+    if (!isSafeBackendPath(path)) {
+      unsafePaths.push(path);
+    } else if (path.startsWith(EXPERIMENTAL_BACKEND_PREFIX)) {
+      experimentalPaths.push(path);
+    } else {
+      generatedBindingPaths.push(path);
+    }
+  }
+
+  return { experimentalPaths, generatedBindingPaths, unsafePaths };
+}
+
+export function isCommitReachableFromNext({ isAncestor }) {
+  return isAncestor;
+}
+
+export function isStalePush({ event, selectedSha, branchTip }) {
+  return event === "push" && selectedSha !== branchTip;
+}
+
+function isReleaseOnlyAdvance(selectedSha, branchTip) {
+  const isAncestor =
+    git(["merge-base", "--is-ancestor", selectedSha, branchTip], {
+      allowFailure: true,
+    }) !== null;
+  if (!isAncestor) {
+    return false;
+  }
+
+  const commits = git(["rev-list", "--reverse", `${selectedSha}..${branchTip}`])
+    .split("\n")
+    .filter(Boolean);
+  if (commits.length === 0) {
+    return false;
+  }
+
+  return commits.every((commit) => {
+    const subject = git(["log", "-1", "--format=%s", commit]);
+    if (!RELEASE_COMMIT_PATTERN.test(subject)) {
+      return false;
+    }
+    const paths = git([
+      "diff-tree",
+      "--no-commit-id",
+      "--name-only",
+      "-r",
+      commit,
+    ])
+      .split("\n")
+      .filter(Boolean);
+    return (
+      paths.length > 0 &&
+      paths.every((path) => RELEASE_COMMIT_PATHS.has(path))
+    );
+  });
+}
+
+function usage() {
+  return [
+    "Usage: release-handoff.mjs validate --sha <40-hex> ",
+    "--branch <origin/next|origin/main> --event <push|workflow_dispatch> ",
+    "--base <origin/main> [--dry-run]",
+  ].join("");
+}
+
+function fail(message) {
+  process.stderr.write(`${message}\n`);
+  process.exitCode = 1;
+}
+
+const VALUE_ARGUMENTS = new Set(["--sha", "--branch", "--event", "--base"]);
+
+function requireCompleteOptions(options) {
+  if (REQUIRED_OPTIONS.some((name) => !options[name])) {
+    throw new Error(usage());
+  }
+}
+
+function validateOptionValues(options) {
+  if (!SHA_PATTERN.test(options.sha)) {
+    throw new Error("--sha must be a 40-character hexadecimal commit SHA");
+  }
+  if (!ALLOWED_BRANCHES.has(options.branch)) {
+    throw new Error("--branch must be origin/next or origin/main");
+  }
+  if (!["push", "workflow_dispatch"].includes(options.event)) {
+    throw new Error("--event must be push or workflow_dispatch");
+  }
+}
+
+function readValueArgument(args, index) {
+  const argument = args[index];
+  if (!VALUE_ARGUMENTS.has(argument)) {
+    throw new Error(`Unknown argument: ${argument}\n${usage()}`);
+  }
+  const value = args[index + 1];
+  if (!value || value.startsWith("--")) {
+    throw new Error(`Missing value for ${argument}\n${usage()}`);
+  }
+  return { name: argument.slice(2), value };
+}
+
+function parseArgs(args) {
+  if (args[0] !== "validate") {
+    throw new Error(usage());
+  }
+
+  const options = { dryRun: false };
+  let index = 1;
+  while (index < args.length) {
+    if (args[index] === "--dry-run") {
+      options.dryRun = true;
+      index += 1;
+    } else {
+      const { name, value } = readValueArgument(args, index);
+      options[name] = value;
+      index += 2;
+    }
+  }
+
+  requireCompleteOptions(options);
+  validateOptionValues(options);
+  return { ...options, sha: options.sha.toLowerCase() };
+}
+
+function git(args, { allowFailure = false } = {}) {
+  try {
+    return execFileSync("git", args, { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
+  } catch (error) {
+    if (allowFailure) {
+      return null;
+    }
+    const detail = error.stderr?.toString().trim();
+    throw new Error(detail || `git ${args.join(" ")} failed`);
+  }
+}
+
+function requireCommit(sha) {
+  if (git(["cat-file", "-e", `${sha}^{commit}`], { allowFailure: true }) === null) {
+    throw new Error(`Commit does not exist: ${sha}`);
+  }
+}
+
+function getBranchTip(options) {
+  const branchTip = git(["rev-parse", options.branch]).toLowerCase();
+  const reachable = git(
+    ["merge-base", "--is-ancestor", options.sha, options.branch],
+    { allowFailure: true },
+  ) !== null;
+
+  if (!isCommitReachableFromNext({ isAncestor: reachable })) {
+    throw new Error(`${options.sha} is not reachable from ${options.branch}`);
+  }
+  return branchTip;
+}
+
+function getSkipResult(options) {
+  const message = git(["log", "-1", "--format=%B", options.sha]);
+  if (hasSkipAlphaMarker(message)) {
+    return { selectedSha: options.sha, status: "skipped", dryRun: options.dryRun };
+  }
+  return null;
+}
+
+function getReadyResult(options) {
+  const changedPaths = git([
+    "diff",
+    "--name-only",
+    options.base,
+    options.sha,
+    "--",
+    "packages/backend",
+  ]).split("\n");
+  const { experimentalPaths, generatedBindingPaths, unsafePaths } =
+    classifyBackendPaths(changedPaths);
+  const generatedWithoutExperimentalSource =
+    generatedBindingPaths.length > 0 && experimentalPaths.length === 0;
+  const blockedPaths = generatedWithoutExperimentalSource
+    ? [...unsafePaths, ...generatedBindingPaths]
+    : unsafePaths;
+  if (blockedPaths.length > 0) {
+    throw new Error(
+      `Stable backend paths differ from ${options.base}: ${blockedPaths.join(", ")}`,
+    );
+  }
+
+  return {
+    selectedSha: options.sha,
+    status: "ready",
+    dryRun: options.dryRun,
+    experimentalPaths,
+    generatedBindingPaths,
+  };
+}
+
+function validate(options) {
+  requireCommit(options.sha);
+  const branchTip = getBranchTip(options);
+  const stale = isStalePush({
+    event: options.event,
+    selectedSha: options.sha,
+    branchTip,
+  });
+  if (stale && !isReleaseOnlyAdvance(options.sha, branchTip)) {
+    return {
+      selectedSha: options.sha,
+      status: "stale",
+      dryRun: options.dryRun,
+      branchTip,
+    };
+  }
+
+  return getSkipResult(options) ?? getReadyResult(options);
+}
+
+function main() {
+  try {
+    const result = validate(parseArgs(process.argv.slice(2)));
+    process.stdout.write(`${JSON.stringify(result)}\n`);
+  } catch (error) {
+    fail(error.message);
+  }
+}
+
+if (import.meta.url === `file://${process.argv[1]}`) {
+  main();
+}

